CREATE POLICY "signed in crest reads" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='team-crests'); CREATE POLICY "own crest uploads" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='team-crests' AND (storage.foldername(name))[1]=auth.uid()::text); CREATE POLICY "own crest removal" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='team-crests' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE OR REPLACE FUNCTION public.guard_match_finish() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND OLD.status='finished' AND (to_jsonb(NEW)-'pelada_closed') IS DISTINCT FROM (to_jsonb(OLD)-'pelada_closed') THEN RAISE EXCEPTION 'A rodada encerrada não pode ser alterada'; END IF; IF TG_OP='UPDATE' AND OLD.pelada_closed AND NOT NEW.pelada_closed THEN RAISE EXCEPTION 'A pelada já foi encerrada'; END IF; IF TG_OP='UPDATE' AND NEW.pelada_id IS DISTINCT FROM OLD.pelada_id THEN RAISE EXCEPTION 'A rodada não pode mudar de pelada'; END IF; IF NEW.pelada_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.matches WHERE id=NEW.pelada_id AND (pelada_closed OR creator_id IS DISTINCT FROM NEW.creator_id OR pelada_id IS NOT NULL)) THEN RAISE EXCEPTION 'Pelada inválida ou encerrada'; END IF; IF TG_OP='UPDATE' AND NEW.status='finished' AND OLD.status IS DISTINCT FROM 'finished' THEN UPDATE public.match_players SET final_team=team,victory_points=CASE WHEN presence='confirmed' AND ((team='colete' AND COALESCE(NEW.score_team_a,0)>COALESCE(NEW.score_team_b,0)) OR (team='sem_colete' AND COALESCE(NEW.score_team_b,0)>COALESCE(NEW.score_team_a,0))) THEN 2 ELSE 0 END WHERE match_id=NEW.id; NEW.finished_at:=COALESCE(NEW.finished_at,now());NEW.clock_seconds:=OLD.clock_seconds+CASE WHEN OLD.clock_running_at IS NULL THEN 0 ELSE GREATEST(0,EXTRACT(epoch FROM NEW.finished_at-OLD.clock_running_at)::integer) END;NEW.clock_running_at:=NULL; END IF; RETURN NEW; END $$;
COMMENT ON TABLE public.match_roles IS 'Per-pelada MESARIO delegation. ADMIN derives from creator_id, PLAYER is default; max two assignments through assign_match_mesario.';